examples.template:
MonarchDeviceFrame(
    {{label}},
    screenSize: CGSize(width: {{width}}, height: {{height}}),
    statusBarTime: {{statusBarTime}}
) {
    VStack(spacing: theme.spacing.space3) {
        MonarchAvatar(image: nil, name: {{name}}, size: .lg)
        Text({{name}}).monarchTextStyle(.bodyStrong)
        Text({{tagline}})
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
        MonarchButton({{links.0}}, variant: .secondary, fullWidth: true) {}
        MonarchButton({{links.1}}, variant: .secondary, fullWidth: true) {}
        MonarchButton({{links.2}}, variant: .secondary, fullWidth: true) {}
    }
    .multilineTextAlignment(.center)
    .padding(.horizontal, theme.spacing.space4)
    .padding(.vertical, theme.spacing.space6)
}

